curl -s "https://calendar.google.com/calendar/ical/elia%40bencnaan.net/private-ac7f55e7ee425d0cc58b9c78871f165a/basic.ics" 2>/dev/null | awk '
BEGIN { found=0; event="" }
/^BEGIN:VEVENT/ { found=1; event=""; next }
found { event = event $0 "\n" }
/^END:VEVENT/ && found {
  if (event ~ /202608/) {
    print event
  }
  found=0; event=""
}' | grep -A2 "DTSTART.*202608" | grep -v "^--$" | head -40

curl -s "https://calendar.google.com/calendar/ical/elia%40bencnaan.net/private-ac7f55e7ee425d0cc58b9c78871f165a/basic.ics" 2>/dev/null | awk '
/^BEGIN:VEVENT/ { 
  if (prev_event) print prev_event "\n---"
  prev_event = $0; next
}
prev_event { 
  prev_event = prev_event "\n" $0
}
/^END:VEVENT/ {
  if (prev_event ~ /202608/) print prev_event
  prev_event = ""
}' | grep -E "(SUMMARY|DTSTART|DTEND)" | head -60
